// נוצר אוטומטית על ידי tools/build-gas.mjs. אין לערוך ידנית.
// Apps Script אינו מספק setTimeout; פעולות מושהות מצטברות ורצות בסוף הבקשה.
var __timers = [];
function setTimeout(fn) { __timers.push(fn); return {}; }
if (typeof structuredClone === 'undefined') { var structuredClone = function (o) { return o === undefined ? undefined : JSON.parse(JSON.stringify(o)); }; }
var __defs = {}; var __cache = {};
function __req(id) {
  if (__cache[id]) return __cache[id];
  var m = __defs[id]();
  __cache[id] = m;
  return m;
}
__defs["app/js/store.js"] = function () {
// שכבת שמירה לדמו ולשרת העתידי. כלל מרכזי (DEV_PLAN, "כלל חיבור לשרת"): אין "הצלחה" לפני שמירה בפועל.
// commit כותב קודם לשכבת האחסון, ורק אם הכתיבה הצליחה מתעדכן המצב בזיכרון. כשל = SaveError, המצב נשאר כפי שהיה,
// ושום דבר לא נשמר חלקית. ניסיון חוזר בטוח כי הפעולה מחושבת מחדש מהמצב השמור ולא מהמצב שנכשל.
// אחסון (backend) הוא אובייקט { load(): root | null, save(root): void (זורק בכשל, ואטומי) }.

class SaveError extends Error {
  constructor(detail) {
    super('השמירה נכשלה, ולכן הפעולה לא בוצעה ושום דבר לא נשמר. אפשר לנסות שוב.');
    this.name = 'SaveError';
    this.detail = detail || '';
  }
}

function createStore({ backend, init, migrate = (x) => x }) {
  let memory = null;
  let loadFailed = false; // קריאה שנכשלה: אסור לכתוב נתוני התחלה מעל נתונים קיימים שלא הצלחנו לקרוא
  function get() {
    if (memory) return memory;
    let loaded = null;
    try { loaded = backend.load(); loadFailed = false; } catch (e) { loaded = null; loadFailed = true; }
    const m = loaded ? migrate(loaded) : null;
    // שדרוג פורמט (migrate החזיר מבנה אחר): קודם גיבוי של המקור כפי שנקרא. אם הגיבוי נכשל לא ממשיכים ולא כותבים כלום (COMPATIBILITY_POLICY, סעיף 4).
    if (m && m !== loaded && backend.archive) {
      try { backend.archive(loaded); } catch (e) { loadFailed = true; throw new Error('הגיבוי שלפני השדרוג נכשל, ולכן הנתונים לא נטענו. נסו שוב.'); }
    }
    if (m) { memory = m; return memory; }
    const fresh = init(loaded);
    if (loadFailed) { memory = fresh; return memory; }
    try { backend.save(fresh); } catch (e) { /* הדמו ממשיך מהזיכרון; פעולה בפועל תיכשל בגלוי */ }
    memory = fresh;
    return memory;
  }
  function commit(next) {
    if (loadFailed) throw new SaveError('הנתונים לא נטענו, לכן אי אפשר לשמור');
    try { backend.save(next); } catch (e) { throw new SaveError(e && e.message); }
    memory = next;
    return next;
  }
  // שמירה אסינכרונית (שרת): הצלחה רק אחרי שהאחסון אישר. בכשל התוצאה בפועל אינה ודאית (ייתכן שהכתיבה הושלמה והאישור אבד),
  // ולכן מבטלים את הזיכרון והמצב נטען מחדש מהאחסון, שהוא מקור האמת.
  function commitAsync(next) {
    if (loadFailed) throw new SaveError('הנתונים לא נטענו, לכן אי אפשר לשמור');
    try { (backend.saveAsync ? backend.saveAsync(next) : backend.save(next)); } catch (e) { memory = null; throw new SaveError(e && e.message); }
    memory = next;
    return next;
  }
  // טעינה מחדש מהאחסון (למשל אחרי כשל, כדי לוודא שהזיכרון תואם למה שנשמר)
  function reload() { memory = null; loadFailed = false; return get(); }
  return { get, commit, commitAsync, reload };
}

// עסקה לבקשה אחת בשרת: כל השינויים מצטברים בצד, ומתפרסמים רק אחרי flush מוצלח (כתיבה אסינכרונית שאושרה).
function createTxStore(store) {
  let pending = null;
  return {
    get: () => pending || store.get(),
    commit(next) { pending = next; return next; },
    hasPending: () => !!pending,
    flush() { if (!pending) return; const p = pending; store.commitAsync(p); pending = null; },
  };
}

// ---------- אחסון localStorage (הדמו) ----------
function localBackend(storage, key) {
  return {
    load() { const raw = storage.getItem(key); return raw ? JSON.parse(raw) : null; },
    save(root) { storage.setItem(key, JSON.stringify(root)); },
    archive(raw) { storage.setItem(key + '-pre-migration', JSON.stringify(raw)); },
  };
}

// עטיפה להדמיית כשל כתיבה (ארגז בדיקות בדמו)
function failingBackend(inner, shouldFail) {
  return {
    load: () => inner.load(),
    save(root) { if (shouldFail()) throw new Error('כשל כתיבה מדומה'); inner.save(root); },
  };
}

// ---------- חלוקה לקבצים (כמו במבנה ה-Drive המתוכנן: קובץ לכל מחזור, פנקס נפרד) ----------
function splitRoot(root) {
  const { cycles = [], notesBook, ...rest } = root;
  const files = { 'meta.json': { ...rest, cycleIds: cycles.map((c) => c.id) } };
  for (const c of cycles) files[`cycles/${c.id}.json`] = c;
  if (notesBook !== undefined) files['notes.json'] = notesBook;
  return files;
}
function joinRoot(files) {
  const meta = files['meta.json'];
  if (!meta) return null;
  const { cycleIds, ...rest } = meta;
  const cycles = cycleIds.map((id) => {
    const c = files[`cycles/${id}.json`];
    if (!c) throw new Error('קובץ מחזור חסר: ' + id);
    return c;
  });
  const root = { ...rest, cycles };
  if (files['notes.json'] !== undefined) root.notesBook = files['notes.json'];
  return root;
}

// ---------- סימולטור Drive מקומי ----------
// כתיבה אטומית: כל הקבצים החדשים נכתבים לאזור ביניים, ורק כשכולם הצליחו הם מחליפים את הקיימים.
// נכתבים רק קבצים ששונו. ניתן להזריק כשל בכתיבת הקובץ ה-N (failOnWrite) או בקריאה.
function createDriveSim() {
  let files = {};
  const sim = {
    failOnWrite: 0, // 1 = הקובץ הראשון שישונה ייכשל; 0 = אין כשל
    failLoad: false,
    latencyMs: 0,
    failAsync: '', // 'before' = הכתיבה נכשלת; 'after' = הכתיבה הושלמה אך האישור אבד (ניתוק); מתאפס אחרי שימוש אחד
    asyncWrites: 0,
    lastWrite: { changed: [], total: 0 },
    archives: [], failArchive: false, // גיבויי מקור שנשמרו לפני שדרוג פורמט
    get files() { return Object.keys(files); },
    backend: {
      saveAsync(root) {
        if (sim.latencyMs) new Promise((r) => setTimeout(r, sim.latencyMs));
        const mode = sim.failAsync;
        sim.failAsync = '';
        if (mode === 'before') throw new Error('כשל מדומה: השרת לא זמין');
        sim.backend.save(root);
        sim.asyncWrites += 1;
        if (mode === 'after') throw new Error('כשל מדומה: הקשר נותק לפני אישור הכתיבה');
      },
      archive(raw) {
        if (sim.failArchive) throw new Error('כשל גיבוי מדומה');
        sim.archives.push(structuredClone(raw));
      },
      load() {
        if (sim.failLoad) throw new Error('כשל קריאה מדומה');
        return Object.keys(files).length ? joinRoot(structuredClone(files)) : null;
      },
      save(root) {
        const next = splitRoot(structuredClone(root));
        const changed = Object.keys(next).filter((k) => JSON.stringify(next[k]) !== JSON.stringify(files[k]));
        const removed = Object.keys(files).filter((k) => !(k in next));
        const staged = {};
        changed.forEach((k, i) => {
          if (sim.failOnWrite && i + 1 === sim.failOnWrite) throw new Error('כשל מדומה בכתיבת ' + k);
          staged[k] = next[k];
        });
        files = { ...Object.fromEntries(Object.entries(files).filter(([k]) => !removed.includes(k))), ...staged };
        sim.lastWrite = { changed, total: Object.keys(next).length };
      },
    },
  };
  return sim;
}

return { SaveError, createStore, createTxStore, localBackend, failingBackend, splitRoot, joinRoot, createDriveSim };
};

__defs["app/js/rubric-defaults.js"] = function () {
// מחווני ברירת מחדל לעבודת הגמר במערכות רפואיות (תשפ"ח), מתוך תוכנית הלימודים הרשמית ("מבנה עבודת הגמר", עמ' 11-15,
// ותיאורי הרמות ב"מחוון הערכה לפי מודל הרמזור", עמ' 55-59). הציון הוא על העבודה הכתובה בלבד (0 עד 100).
// זו הצעה בלבד: המורה חופשי לערוך כל מחוון, קריטריון, ניקוד וטקסט. הבחינה בעל פה אינה חלק מהמערכת.
// ניקוד הסעיפים לפי "מבנה עבודת הגמר" (סכום הפרקים 100). כשהמחוון בעמ' 55-59 נותן ערך אחר לשורה, נלקח הערך מהמבנה.
// הפרדה בין רמות: ירוק = שליטה מלאה, צהוב = שליטה חלקית (60%-80%), אדום = טעון שיפור (0%-40%). אלה הכוונה בלבד:
// המורה נותן כל ציון מ-0 עד המקסימום של הקריטריון.

const c = (name, max, green, yellow, red, extra = {}) => ({ name, max, green, yellow, red, ...extra });

const BAND_HINT = { green: 'ירוק — מצטיין (100%)', yellow: 'צהוב — מיומן (60%–80%)', red: 'אדום — טעון שיפור (0%–40%)' };

// סיכוני פסילה (לפי עמ' 58-59 במחוון). אינם משנים ציון: המורה מסמן, והתלמיד מקבל הודעה ברורה בשליחת המשוב.
// השחרה: רק פרטי מטופלים ומסמכים רפואיים שלהם, לא פרטי התלמידים ובית הספר.
// שימוש ב-AI: אין מעקב, זיהוי או אכיפה, ואין סימון פסילה בגללו (החלטת אורי, 1.11.2026).
const RISK_FLAGS = [
  { key: 'identifying', label: 'חשיפת פרט מזהה של מטופל', studentText: 'במסמך נמצא פרט שעלול לזהות מטופל (למשל שם, מספר זהות או כתובת של המטופל, או פרטים מזהים במסמך רפואי שלו). הדרישה להשחרה חלה על פרטי המטופלים ועל המסמכים הרפואיים שלהם, לא על שמך או על פרטי בית הספר שנדרשים בעבודה. אם לא יוסר או יושחר, העבודה עלולה להיפסל.' },
  { key: 'appendix', label: 'נספח חובה חסר', studentText: 'חסר נספח חובה. אם לא יצורף נספח החובה, העבודה עלולה להיפסל.' },
];

const DEFAULT_RUBRICS = [
  {
    key: 'intro', name: 'הקדמה', total: 3,
    criteria: [
      c('הקדמה: הצגת הנושא, הצגת המטופלים ותודות', 3,
        'ארגון: הצגה לוגית מובנית של המחלה, נימוק קוהרנטי של המוטיבציה, סקירה שיטתית של הפרקים. עומק קליני: הצגה מדויקת של המחלה (הגדרה ונתון אפידמיולוגי עדכני) ומקורו, ופירוט נסיבות המטופלים בטבלה. מקוריות: כתיבה עצמאית, אנושית ואותנטית, חופשית מתבניות טקסט מנופחות; תודות אישיות.',
        'ארגון: הצגת המחלה קיימת, אך הסקירה של מבנה העבודה שטוחה או חסרה. עומק קליני: הצגה נכונה ללא ביסוס אפידמיולוגי; חסרים נתונים קליניים מרכזיים; אי-דיוקים בטבלת המטופלים. מקוריות: ניסוח בסיסי שנשען בחלקו על תבניות טקסט כלליות; תודות תקינות אך גנריות.',
        'ארגון: היעדר ארגון מבני של המבוא, היעדר נימוק לבחירת הנושא. עומק קליני: הצגת מחלה חלקית או שגויה רפואית; היעדר הצגה קלינית של המטופלים או חוסר בנתוני הטבלה. מקוריות: העתקת מבוא גנרי ללא עיבוד וכתיבה עצמאית; תודות מועתקות.'),
    ],
  },
  {
    key: 'chapterA', name: 'פרק א׳: רקע מדעי (סקירת ספרות ומאמר מדעי)', total: 21,
    criteria: [
      c('א1: בסיס מדעי, אנטומיה ופיזיולוגיה (עד 6 עמודים)', 6,
        'ארגון: חלוקה היררכית לוגית לתתי-פרקים; רצף טיעוני המקשר בין אנטומיה, משוב וקליניקה. עומק קליני: תיאור מדויק ומלא של האנטומיה והפיזיולוגיה של המערכת, כולל מנגנוני משוב, בהיקף שנקבע. מקוריות: סינתזה עצמאית של מספר מקורות אקדמיים לסצנה אחידה תוך שיוך עובדות למקורות.',
        'ארגון: החלוקה לתתי-פרקים שטוחה או אסוציאטיבית; חסרות תת-כותרות מרכזיות. עומק קליני: תיאור אנטומי נכון אך שטחי; היעדר הסבר מעמיק על מנגנוני משוב; חריגה מההיקף (6 עמ\'). מקוריות: הסתמכות בולטת על מבנה של מקור מידע יחיד; ניסוח שנשען על טקסט מקורי ללא עיבוד.',
        'ארגון: טקסט כבלוק רציף ללא חלוקה מובנית; היעדר רצף טיעוני. עומק קליני: שגיאות רפואיות קשות, תיאור דל ושגוי של המערכת, היעדר מנגנוני משוב. מקוריות: העתקת תוכן ללא עיבוד עצמאי (Copy-Paste); היעדר שיוך למקורות.'),
      c('א2: קליניקה של המחלה', 8,
        'ארגון: כיסוי מלא של רכיבי הקליניקה (הגדרה ושכיחות, אטיולוגיה, פתופיזיולוגיה, ביטויים קליניים, אבחון וטיפול); חלוקה ברורה לרמות מניעה (ראשונית, שניונית, שלישונית). עומק קליני: מינוח רפואי מדויק; הסבר הקשר בין אטיולוגיה לפתופיזיולוגיה לקליניקה; פרוטוקולי טיפול. מקוריות: ניתוח קליני עצמאי ומקורי המשקף הבנה עמוקה, ללא העתקה.',
        'ארגון: רכיבים שטחיים; חלוקה חלקית לרמות מניעה; אין הבחנה בין תרופתי ללא-תרופתי. עומק קליני: תיאור בסיסי של הטיפול ללא הנמקה קלינית מעמיקה; כתיבה תיאורית בלבד. מקוריות: ניסוח המסתמך בחלקו על מקור יחיד ללא עיבוד קליני עצמאי.',
        'ארגון: היעדר ארגון ברור; אין חלוקה לרמות מניעה. עומק קליני: חסרים רכיבים קליניים מרכזיים (שכיחות, אבחון, טיפול); טעויות מדעיות מהותיות. מקוריות: העתקה ישירה של קליניקה גנרית ללא הקשר למטופלים; טקסט מועתק.'),
      c('א3: סיכום מאמר מדעי חדשני (עד 5 שנים, לא מאמר סקירה)', 2,
        'ארגון: פירוק מתודולוגי מובחן; הצלבה ברורה בין שיטות, ממצאים והשלכותיהם. עומק קליני: מאמר עדכני (עד 5 שנים); ניתוח ביקורתי, הבחנה בין עיקר לטפל, הסבר נתונים סטטיסטיים. מקוריות: יצירת תרשים זרימה או סכמה חדשה ומעובדת המארגנת מחדש את המאמר, בתיווך מילולי.',
        'ארגון: הפרדה בסיסית בין שיטות לתוצאות; הצגת הרקע והתוצאות חלקית. עומק קליני: תיאור סטטי של התוצאות ללא ניתוח משמעותן; היעדר הבחנה בין ממצאים. מקוריות: ייצוג חזותי בסיסי בלבד, ללא הסבר מעמיק וללא ניתוח.',
        'ארגון: היעדר הבחנה בין שיטות לתוצאות; הצגה מבולבלת של ממצאי המחקר. עומק קליני: מאמר ישן מ-5 שנים או מאמר סקירה; תרגום אוטומטי; סילוף תוצאות המחקר. מקוריות: היעדר ייצוג חזותי מעובד, או הדבקת צילום מסך בלועזית ישר מהמאמר ללא תרגום.'),
      c('א4: קישור המאמר לרקע העיוני', 2,
        'הסבר מדויק ומנומק כיצד המאמר מעדכן את ההבנה של הניהול הקליני ביחס לרקע העיוני שסוכם.',
        'קישור כללי בלבד בין המאמר לרקע העיוני, ללא הסבר מפורט.',
        'אין קישור בין המאמר לרקע העיוני, או שהקישור שגוי מדעית.'),
      c('א5: סיכום קבוצתי, שילוב ופער מחקרי', 3,
        'שילוב שלושת המאמרים לתובנה משותפת, וזיהוי ממוקד של פערי ידע או כיוון מחקר.',
        'סיכום חלקי, תובנה משותפת לא ברורה, פער מחקרי כללי מדי.',
        'אין סיכום קבוצתי משותף (רק מאמר אחד); אין הגדרת פער ידע.'),
    ],
  },
  {
    key: 'chapterB', name: 'פרק ב׳: סיפורי המטופלים (לכל מטופל)', total: 32,
