  };
}
function sha256Hex_(text) {
  var d = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, text, Utilities.Charset.UTF_8); var h = '';
  for (var i = 0; i < d.length; i++) { var b = d[i] < 0 ? d[i] + 256 : d[i]; h += (b < 16 ? '0' : '') + b.toString(16); }
  return h;
}

function checkNow_() {
  var props = PropertiesService.getScriptProperties();
  var res = UrlFetchApp.fetch(UPDATES_URL, { muteHttpExceptions: true, followRedirects: true });
  props.setProperty('LAST_CHECK', new Date().toISOString());
  if (res.getResponseCode() !== 200) { log_('updates http ' + res.getResponseCode()); return { checked: true, updated: false, reason: 'updates_http_' + res.getResponseCode() }; }
  var rel = parseRelease(res.getContentText(), PUBLIC_KEY, verifyDeps_());
  if (!rel.ok) { log_('release rejected: ' + rel.reason); return { checked: true, updated: false, reason: 'release_' + rel.reason }; }
  var payload = rel.payload;
  var failed = null; try { failed = JSON.parse(props.getProperty('UPD_FAIL') || 'null'); } catch (err) { failed = null; }
  var installed = Number(libBuild()); if (isNaN(installed)) installed = null;
  var d = decide(payload, { installed: installed, storedSeq: Number(props.getProperty('UPD_SEQ') || 0), bucket: bucket_(), uploadActive: !!CacheService.getScriptCache().get('upl_active'), failed: failed });
  if (d.reason === 'old_seq') log_('ignored old seq ' + payload.seq);
  if (d.action !== 'update') {
    if (d.reason !== 'old_seq' && d.seq > Number(props.getProperty('UPD_SEQ') || 0)) props.setProperty('UPD_SEQ', String(d.seq));
    if (d.reason === 'not_in_bucket') log_('not in rollout bucket ' + bucket_() + ' >= ' + payload.percent);
    if (d.reason === 'upload_active') log_('deferred: upload active');
    return { checked: true, updated: false, reason: d.reason, version: payload.version };
  }
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(10000)) return { checked: true, updated: false, reason: 'busy' };
  try {
    var r = applyPackage_(payload);
    props.setProperty('UPD_SEQ', String(payload.seq)); props.setProperty('UPD_FAIL', 'null');
    log_('updated ' + installed + ' -> ' + payload.version);
    return { checked: true, updated: true, from: installed, to: payload.version, deployment: r.deploymentId };
  } catch (err) {
    var prev = failed && failed.version === payload.version ? failed.count : 0;
    props.setProperty('UPD_FAIL', JSON.stringify({ version: payload.version, count: prev + 1 }));
    log_('update failed (' + (prev + 1) + '): ' + String(err && err.message).slice(0, 140));
    return { checked: true, updated: false, reason: 'update_failed' };
  } finally { lock.releaseLock(); }
}

function api_(method, path, body) {
  var res = UrlFetchApp.fetch('https://script.googleapis.com/v1' + path, {
    method: method, contentType: 'application/json', muteHttpExceptions: true,
    headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken(), 'X-Goog-User-Project': QUOTA_PROJECT },
    payload: body ? JSON.stringify(body) : undefined
  });
  var code = res.getResponseCode();
  if (code < 200 || code >= 300) throw new Error('api ' + method + ' ' + path.split('/').slice(-1)[0] + ' ' + code + ' ' + res.getContentText().slice(0, 160));
  return JSON.parse(res.getContentText());
}

function webDeployment_(id) {
  var ds = api_('GET', '/projects/' + id + '/deployments').deployments || [];
  var web = ds.filter(function (d) { return d.deploymentConfig && d.deploymentConfig.versionNumber && (d.entryPoints || []).some(function (e) { return e.entryPointType === 'WEB_APP'; }); })[0];
  if (!web) throw new Error('web app deployment not found');
  return web;
}

function fillShell_(src) {
  return src.split(TOKENS_.UPDATES_URL).join(UPDATES_URL).split(TOKENS_.QUOTA_PROJECT).join(QUOTA_PROJECT).split(TOKENS_.PUBLIC_KEY).join(PUBLIC_KEY).split(TOKENS_.TRIGGER_EVERY_MIN).join(String(TRIGGER_EVERY_MIN));
}

// בודק שהשרת עונה בגרסה החדשה בכתובת הפריסה (ping ציבורי). נותן ל-Google כמה שניות להפיץ את הפריסה.
function respondsWithVersion_(deploymentId, version) {
  for (var i = 0; i < 3; i++) {
    try {
      var r = UrlFetchApp.fetch('https://script.google.com/macros/s/' + deploymentId + '/exec?action=ping', { muteHttpExceptions: true, followRedirects: true });
      if (r.getResponseCode() === 200 && JSON.parse(r.getContentText()).build === String(version)) return true;
    } catch (err) { /* ננסה שוב */ }
    if (typeof Utilities.sleep === 'function') Utilities.sleep(2500);
  }
  return false;
}

// מוריד את החבילה, מאמת אותה, מעלה את הקבצים, יוצר גרסה ומפנה אליה את הפריסה (אותה כתובת). הנתונים ב-Drive אינם נוגעים בתהליך.
function applyPackage_(payload) {
  var base = UPDATES_URL.replace(/latest\.json$/, '');
  var pr = UrlFetchApp.fetch(base + payload.pkg, { muteHttpExceptions: true, followRedirects: true });
  if (pr.getResponseCode() !== 200) throw new Error('package http ' + pr.getResponseCode());
  var text = pr.getContentText();
  if (sha256Hex_(text) !== payload.sha256) throw new Error('package hash mismatch');
  var pkg = JSON.parse(text);
  var id = ScriptApp.getScriptId();
  var current = api_('GET', '/projects/' + id + '/content');
  var curManifest = current.files.filter(function (f) { return f.name === 'appsscript'; })[0];
  var scopes = (JSON.parse(curManifest.source).oauthScopes) || [];
  var problems = validatePackage(pkg, payload, scopes);
  if (problems.length) throw new Error('package rejected: ' + problems[0]);
  var web = webDeployment_(id);
  var prevVersion = web.deploymentConfig.versionNumber;
  var files = pkg.files.map(function (f) { return { name: f.name, type: f.type, source: f.name === 'Shell' ? fillShell_(f.source) : f.source }; });
  api_('PUT', '/projects/' + id + '/content', { files: files });
  var v = api_('POST', '/projects/' + id + '/versions', { description: 'v' + payload.version });
  api_('PUT', '/projects/' + id + '/deployments/' + web.deploymentId, { deploymentConfig: { scriptId: id, versionNumber: v.versionNumber, manifestFileName: 'appsscript', description: 'v' + payload.version } });
  if (!respondsWithVersion_(web.deploymentId, payload.version)) {
    api_('PUT', '/projects/' + id + '/deployments/' + web.deploymentId, { deploymentConfig: { scriptId: id, versionNumber: prevVersion, manifestFileName: 'appsscript', description: 'rollback to ' + prevVersion } });
    throw new Error('new version did not respond; rolled back to version ' + prevVersion);
  }
  return { deploymentId: web.deploymentId, version: v.versionNumber };
}

// ===== מוטמע מ-app/js/ed25519.js =====
// אימות חתימה דיגיטלית Ed25519 (RFC 8032), בלי תלות חיצונית. מיועד לאימות בלבד (החתימה נעשית אצל אורי בכלי השחרור).
// נכתב כפונקציה אחת עצמאית ללא תחביר מודולים פנימי, כדי שאפשר יהיה להטמיע את אותו הקוד בדיוק בשרת של המורה (Apps Script)
// ובמשגר (דפדפן). sha512 מוזרק: (מערך בתים 0..255) => מערך בתים 0..255. BigInt נתמך ב-V8 של Apps Script.
// מחזיר true רק לחתימה תקינה. כל קלט פגום מחזיר false ולא זורק.
function ed25519Verify(sig, msg, pub, sha512) {
  try {
    var BI = BigInt; // בלי מילולי BigInt (למשל 1n): בדיקת התחביר של Google בהעלאת פרויקט דוחה אותם
    if (!sig || !pub || sig.length !== 64 || pub.length !== 32) return false;
    var P = (BI("1") << BI("255")) - BI("19");
    var L = (BI("1") << BI("252")) + BI("27742317777372353535851937790883648493");
    var mod = function (a) { var r = a % P; return r >= BI("0") ? r : r + P; };
    var pow = function (b, e) { var r = BI("1"); b = mod(b); while (e > BI("0")) { if (e & BI("1")) r = r * b % P; b = b * b % P; e >>= BI("1"); } return r; };
    var inv = function (a) { return pow(a, P - BI("2")); };
    var D = mod(-BI("121665") * inv(BI("121666")));
    var I = pow(BI("2"), (P - BI("1")) / BI("4"));
    var le = function (bytes) { var n = BI("0"); for (var i = bytes.length - 1; i >= 0; i--) n = (n << BI("8")) | BigInt(bytes[i]); return n; };
    var dec = function (b) {
      var bb = Array.prototype.slice.call(b); var sign = bb[31] >> 7; bb[31] &= 127;
      var y = le(bb); if (y >= P) return null;
      var y2 = y * y % P; var x2 = mod((y2 - BI("1")) * inv(D * y2 + BI("1")));
      var x = pow(x2, (P + BI("3")) / BI("8"));
      if (mod(x * x - x2) !== BI("0")) x = x * I % P;
      if (mod(x * x - x2) !== BI("0")) return null;
      if (x === BI("0") && sign) return null;
      if (Number(x & BI("1")) !== sign) x = P - x;
      return [x, y, BI("1"), x * y % P];
    };
    var add = function (p, q) {
      var A = mod((p[1] - p[0]) * (q[1] - q[0])); var B = mod((p[1] + p[0]) * (q[1] + q[0]));
      var C = mod(p[3] * BI("2") * D * q[3]); var DD = mod(p[2] * BI("2") * q[2]);
      var E = B - A; var F = DD - C; var G = DD + C; var H = B + A;
      return [mod(E * F), mod(G * H), mod(F * G), mod(E * H)];
    };
    var mul = function (p, k) { var r = [BI("0"), BI("1"), BI("1"), BI("0")]; var q = p; while (k > BI("0")) { if (k & BI("1")) r = add(r, q); q = add(q, q); k >>= BI("1"); } return r; };
    var by = mod(BI("4") * inv(BI("5"))); var byBytes = []; for (var i = 0, t = by; i < 32; i++, t >>= BI("8")) byBytes.push(Number(t & BI("255")));
    var B0 = dec(byBytes);
    var R = dec(Array.prototype.slice.call(sig, 0, 32)); var A0 = dec(pub);
    var S = le(Array.prototype.slice.call(sig, 32, 64));
    if (!R || !A0 || !B0 || S >= L) return false;
    var hin = Array.prototype.slice.call(sig, 0, 32).concat(Array.prototype.slice.call(pub), Array.prototype.slice.call(msg));
    var h = le(sha512(hin)) % L;
    var left = mul(B0, S); var right = add(R, mul(A0, h));
    return mod(left[0] * right[2]) === mod(right[0] * left[2]) && mod(left[1] * right[2]) === mod(right[1] * left[2]);
  } catch (e) { return false; }
}

// ===== מוטמע מ-app/js/update-package.js =====
// פורמט חבילת העדכון וכללי ההחלטה. לוגיקה טהורה, בלי Node ובלי דפדפן, כדי שאותו קוד בדיוק ירוץ בשלושה מקומות:
// בכלי השחרור של אורי (חתימה ובדיקה), במשגר (התקנה ראשונה) ובשרת של כל מורה (עדכון עצמי).
// כל התלות בסביבה מוזרקת (deps): sha512, b64decode ו-utf8, כולן מחזירות/מקבלות מערכי בתים 0..255.
//
// שני קבצים מתפרסמים ב-GitHub Pages:
//   latest.json   = { format: 1, payload: "<מחרוזת JSON>", sig: "<חתימה Ed25519 על בתי ה-UTF-8 של המחרוזת, base64>" }
//   pkg-<גרסה>.json = { format: 1, version, files: [ { name, type, source } ] }
// payload: { seq, version, percent, urgent, hold, pkg, sha256 }. seq עולה בכל פרסום (גם בחזרה לאחור) ומונע שימוש חוזר בחתימה ישנה.
// החבילה עצמה אינה חתומה: sha256 שלה נמצא בתוך ה-payload החתום, ולכן כל שינוי בה מתגלה.

const PACKAGE_FILES = ['Code', 'Shell', 'appsscript'];
const MAX_VERSION = 100000;
const MAX_PACKAGE_BYTES = 6000000;
const isInt = (n, a, b) => typeof n === 'number' && n % 1 === 0 && n >= a && n <= b;

// פותח ומאמת מעטפת חתומה. מחזיר { ok: true, payload } או { ok: false, reason }.
function parseRelease(text, publicKeyB64, deps) {
  let env;
  try { env = JSON.parse(text); } catch (e) { return { ok: false, reason: 'not_json' }; }
  if (!env || env.format !== 1 || typeof env.payload !== 'string' || typeof env.sig !== 'string' || env.payload.length > 4000) return { ok: false, reason: 'bad_envelope' };
  let sig; let pub;
  try { sig = deps.b64decode(env.sig); pub = deps.b64decode(publicKeyB64); } catch (e) { return { ok: false, reason: 'bad_base64' }; }
  if (!ed25519Verify(sig, deps.utf8(env.payload), pub, deps.sha512)) return { ok: false, reason: 'bad_signature' };
  let p;
  try { p = JSON.parse(env.payload); } catch (e) { return { ok: false, reason: 'payload_not_json' }; }
  if (!p || !isInt(p.seq, 1, 1e12) || !isInt(p.version, 1, MAX_VERSION) || !isInt(p.percent, 0, 100) || typeof p.urgent !== 'boolean' || typeof p.hold !== 'boolean'
    || !/^pkg-\d{1,6}\.json$/.test(String(p.pkg)) || !/^[0-9a-f]{64}$/.test(String(p.sha256))) return { ok: false, reason: 'bad_payload' };
  return { ok: true, payload: { seq: p.seq, version: p.version, percent: p.percent, urgent: p.urgent, hold: p.hold, pkg: p.pkg, sha256: p.sha256 } };
}

// בודק את מבנה החבילה אחרי שה-sha256 שלה אומת. מחזיר רשימת בעיות (ריקה = תקין).
// installedScopes: ההרשאות במניפסט הנוכחי של הפרויקט (null בהתקנה ראשונה). הרשאה חדשה דורשת אישור מחדש של המורה ולכן אסורה בעדכון שקט.
function validatePackage(pkg, payload, installedScopes) {
  const problems = [];
  if (!pkg || pkg.format !== 1 || pkg.version !== payload.version || !Array.isArray(pkg.files)) return ['מבנה חבילה לא תקין או גרסה שאינה תואמת'];
  const names = pkg.files.map((f) => f && f.name);
  if (names.length !== PACKAGE_FILES.length || !PACKAGE_FILES.every((n) => names.indexOf(n) >= 0)) problems.push('קבצי החבילה אינם הקבצים המותרים: ' + names.join(','));
  let total = 0;
  for (const f of pkg.files) {
    if (!f || typeof f.source !== 'string' || f.source.length < 2) { problems.push('קובץ ריק או פגום: ' + (f && f.name)); continue; }
    if (f.type !== (f.name === 'appsscript' ? 'JSON' : 'SERVER_JS')) problems.push('סוג קובץ לא צפוי: ' + f.name);
    total += f.source.length;
  }
  if (total > MAX_PACKAGE_BYTES) problems.push('החבילה גדולה מדי');
  const mf = pkg.files.find((f) => f && f.name === 'appsscript');
  if (mf) {
    let m = null;
    try { m = JSON.parse(mf.source); } catch (e) { problems.push('המניפסט אינו JSON'); }
    if (m) {
      if (m.dependencies && m.dependencies.libraries && m.dependencies.libraries.length) problems.push('החבילה אינה יכולה להסתמך על ספרייה חיצונית');
      if (!m.webapp || m.webapp.executeAs !== 'USER_DEPLOYING' || m.webapp.access !== 'ANYONE_ANONYMOUS') problems.push('הגדרת האפליקציה במניפסט שונה מהמצופה');
      const scopes = Array.isArray(m.oauthScopes) ? m.oauthScopes : [];
      if (installedScopes) { const extra = scopes.filter((s) => installedScopes.indexOf(s) < 0); if (extra.length) problems.push('הרשאה חדשה דורשת אישור מחדש של המורה: ' + extra.join(',')); }
    }
  }
  return problems;
}

// החלטת עדכון. state: { installed (מספר או null), storedSeq, bucket (0..99), uploadActive, failed: { version, count } | null }
// מחזיר { action: 'update' | 'none', reason, seq } . seq מוחזר כדי שהשרת ירשום אותו כשהחתימה תקפה (גם בלי עדכון).
function decide(payload, state) {
  const base = { seq: payload.seq };
  if (payload.seq < (state.storedSeq || 0)) return { ...base, action: 'none', reason: 'old_seq', seq: state.storedSeq };
  if (payload.hold) return { ...base, action: 'none', reason: 'hold' };
  if (state.installed === payload.version) return { ...base, action: 'none', reason: 'up_to_date' };
  if (state.failed && state.failed.version === payload.version && state.failed.count >= 3) return { ...base, action: 'none', reason: 'failed_before' };
  if (!payload.urgent && state.bucket >= payload.percent) return { ...base, action: 'none', reason: 'not_in_bucket' };
  if (state.uploadActive) return { ...base, action: 'none', reason: 'upload_active' };
  return { ...base, action: 'update', reason: 'update' };
}
